#include <iostream>
#include <string>
#include <algorithm>
#include <cmath>

int main() {
    int h, n;
    std::cin >> h >> n;
    int n_minus_one = n - 1;
    std::string binary_rep = std::bitset<32>(n_minus_one).to_string();
    // Extract the last h bits
    binary_rep = binary_rep.substr(32 - h);
    int total = 0;
    bool flip_state = true;
    for (int position = 0; position < h; ++position) {
        if (binary_rep[position] == (flip_state ? '1' : '0')) {
            total += (1 << (h - position));
        } else {
            flip_state = !flip_state;
            total += 1;
        }
    }
    std::cout << total << std::endl;
    return 0;
}
